#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, K, P;
    cin >> N >> K >> P;

    // In any tournament on N vertices, sum of indegrees = N*(N-1)/2.
    // If every indegree <= K, then necessarily N*(N-1)/2 <= N*K, i.e. N-1 <= 2K.
    // Also, the forbidden pattern implies no directed 3-cycle can have a common out-neighbor.
    //
    // Key fact:
    // A tournament with no such forbidden 4-vertex configuration is exactly a transitive tournament.
    // Proof sketch:
    // Any non-transitive tournament contains a directed 3-cycle (standard fact).
    // If there are more vertices, every outside vertex relative to that 3-cycle must either dominate all 3
    // or be dominated by all 3; otherwise another 3-cycle appears with fewer/other vertices.
    // In particular, if some vertex is dominated by all 3, we get the forbidden configuration.
    // Repeating shows only transitive tournaments avoid it.
    //
    // A transitive tournament on distinguishable vertices corresponds to a total order of vertices,
    // hence there are N! such tournaments.
    //
    // In a transitive tournament, indegrees are exactly 0,1,2,...,N-1, so the maximum indegree is N-1.
    // Therefore the condition "indegree of every vertex <= K" holds iff N-1 <= K.
    //
    // Thus the answer is:
    //   N! mod P, if N-1 <= K
    //   0 otherwise

    if (N - 1 > K) {
        cout << 0 % P << '\n';
        return 0;
    }

    long long ans = 1 % P;
    for (long long i = 1; i <= N; ++i) {
        ans = (ans * (i % P)) % P;
    }
    cout << ans % P << '\n';
    return 0;
}

