#include <stdio.h>
#define MOD 1000000007

int main() {
    int N, K, P;
    scanf("%d %d %d", &N, &K, &P);
    int total = 1 << (N*(N-1)/2);
    int ans = 0;
    int edge_idx[N][N];
    int idx = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            edge_idx[i][j] = idx++;
        }
    }
    for (int mask = 0; mask < total; mask++) {
        int indeg[N];
        for (int i = 0; i < N; i++) indeg[i] = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i+1; j < N; j++) {
                int e = edge_idx[i][j];
                if (mask & (1 << e)) {
                    indeg[j]++;
                } else {
                    indeg[i]++;
                }
            }
        }
        int ok = 1;
        for (int i = 0; i < N; i++) {
            if (indeg[i] > K) { ok = 0; break; }
        }
        if (!ok) continue;
        // check condition: for any distinct a,b,c,d, not all six edges a->b, b->c, c->a, a->d, b->d, c->d
        for (int a = 0; a < N && ok; a++) {
            for (int b = a+1; b < N && ok; b++) {
                for (int c = b+1; c < N && ok; c++) {
                    // check if a,b,c form directed 3-cycle
                    int ab = (mask & (1 << edge_idx[a][b])) ? 1 : 0; // 1 means a->b? careful: edge_idx[a][b] defined for a<b. If a<b then bit=1 means a->b else b->a.
                    int bc, ca;
                    if (b < c) bc = (mask & (1 << edge_idx[b][c])) ? 1 : 0;
                    else bc = (mask & (1 << edge_idx[c][b])) ? 0 : 1;
                    if (a < c) ca = (mask & (1 << edge_idx[a][c])) ? 1 : 0;
                    else ca = (mask & (1 << edge_idx[c][a])) ? 0 : 1;
                    // For directed cycle a->b->c->a, we need a->b, b->c, c->a.
                    int a_to_b = (a < b) ? ab : (1-ab);
                    int b_to_c = (b < c) ? bc : (1-bc);
                    int c_to_a = (c < a) ? ca : (1-ca);
                    if (a_to_b && b_to_c && c_to_a) {
                        for (int d = 0; d < N; d++) {
                            if (d == a || d == b || d == c) continue;
                            int a_to_d = (a < d) ? (mask & (1 << edge_idx[a][d])) ? 1 : 0 : (mask & (1 << edge_idx[d][a])) ? 0 : 1;
                            int b_to_d = (b < d) ? (mask & (1 << edge_idx[b][d])) ? 1 : 0 : (mask & (1 << edge_idx[d][b])) ? 0 : 1;
                            int c_to_d = (c < d) ? (mask & (1 << edge_idx[c][d])) ? 1 : 0 : (mask & (1 << edge_idx[d][c])) ? 0 : 1;
                            if (a_to_d && b_to_d && c_to_d) {
                                ok = 0; break;
                            }
                        }
                    }
                }
            }
        }
        if (ok) ans = (ans + 1) % P;
    }
    printf("%d\n", ans);
    return 0;
}

