typedef long long ll;

static ll mod_pow(ll a, ll e, ll mod) {
    ll r = 1 % mod;
    while (e > 0) {
        if (e & 1) r = (r * a) % mod;
        a = (a * a) % mod;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, K;
    ll P;
    if (scanf("%d %d %lld", &N, &K, &P) != 3) return 0;

    if (P == 1) {
        printf("0\n");
        return 0;
    }

    /* In any tournament on N vertices, average indegree is (N-1)/2.
       If every indegree <= K, then necessarily N <= 2K+1. */
    if (N > 2 * K + 1) {
        printf("0\n");
        return 0;
    }

    /* Key fact:
       The forbidden pattern is exactly a directed 3-cycle with a common out-neighbor.
       A tournament avoiding it is transitive.
       Reason: if a tournament has any directed cycle, it has a directed 3-cycle.
       In a nontrivial strongly connected component containing such a 3-cycle, some vertex
       outside the triangle is reachable from it; taking the first such vertex on a path
       yields a common out-neighbor of the triangle, forbidden. Hence every SCC is trivial,
       so the tournament is acyclic, i.e. transitive.

       Therefore valid graphs are exactly transitive tournaments.
       A transitive tournament on N labeled vertices corresponds uniquely to a total order,
       so there are N! of them.

       In a transitive tournament, indegrees are 0,1,...,N-1.
       Thus max indegree = N-1, so the condition indegree <= K for every vertex
       is equivalent to N-1 <= K.
    */
    if (N - 1 > K) {
        printf("0\n");
        return 0;
    }

    ll ans = 1 % P;
    for (int i = 1; i <= N; ++i) {
        ans = (ans * i) % P;
    }

    printf("%lld\n", ans);
    return 0;
}

