            for (int i = 0; i < N; i++) for (int j = i+1; j < N; j++) {
                if (((mask>>idx)&1)==1) { edge[i][j]=1; indeg[j]++; } else { edge[j][i]=1; indeg[i]++; }
                idx++;
            }
            boolean ok = true;
            for (int v=0;v<N;v++) if (indeg[v]>K) { ok=false; break; }
            if (!ok) continue;
            outer: for (int a=0;a<N&&ok;a++) for (int b=0;b<N&&ok;b++) if (a!=b&&edge[a][b]==1) for (int c=0;c<N&&ok;c++) if (c!=a&&c!=b&&edge[b][c]==1&&edge[c][a]==1) for (int d=0;d<N&&ok;d++) if (d!=a&&d!=b&&d!=c&&edge[a][d]==1&&edge[b][d]==1&&edge[c][d]==1) ok=false;
            if (ok) count++;
        }
        System.out.println(count % P);
