public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long MOD;
    static int N, K;

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        K = fs.nextInt();
        MOD = fs.nextLong();

        // In any tournament on N vertices, average indegree is (N-1)/2.
        // If every indegree <= K, then necessarily N <= 2K+1.
        if (N > 2L * K + 1) {
            System.out.println(0);
            return;
        }

        // Key facts:
        // 1) If all indegrees are <= K and N <= 2K+1, then counting such tournaments.
        // 2) The forbidden pattern is exactly a cyclic triangle {a,b,c} with a common out-neighbor d.
        //    In a regular/capped-indegree tournament, this is equivalent to forbidding any cyclic triangle
        //    unless impossible; the only tournaments avoiding it are transitive tournaments.
        // 3) A transitive tournament on labeled vertices corresponds uniquely to a total order,
        //    hence there are N! of them.
        // 4) In a transitive tournament, indegrees are 0,1,...,N-1, so max indegree = N-1.
        //    Therefore all indegrees <= K iff N-1 <= K.
        //
        // So answer is:
        //   N! mod P if N-1 <= K
        //   0 otherwise
        //
        // (This also automatically satisfies the earlier necessary condition.)

        if (N - 1 > K) {
            System.out.println(0);
            return;
        }

        long ans = 1 % MOD;
        for (int i = 2; i <= N; i++) ans = (ans * i) % MOD;
        System.out.println(ans);
    }
